import { getLocale } from "next-intl/server";
/**
 * The layout for every route under `(app)`. Checks, in order:
 *
 * 1. A session, checked here because middleware only reads the cookie.
 *    None → `/login`.
 * 2. Completed onboarding. Incomplete → `/onboarding`. The onboarding
 *    route is a sibling of `(app)`, so this cannot redirect into itself;
 *    if you nest onboarding under `(app)`, skip this check on that route.
 * 3. An active workspace. `ensureUserWorkspace` creates one if none
 *    exists; what a new workspace starts with is the handler
 *    `lib/intelligo.ts` sets with `setWorkspaceCreatedHandler`.
 */

import { eq } from "drizzle-orm";
import { headers } from "next/headers";
import type { ReactNode } from "react";

import {
  auth,
  ensureUserWorkspace,
  getAuthSession,
  getWorkspaceContextById,
} from "@intelligo-dev/auth";
import { db } from "@intelligo-dev/core/db";
import { users } from "@intelligo-dev/core/db/schema";

import { AppSidebar } from "@/components/shell/app-sidebar";
import { PageTransition } from "@/components/shell/page-transition";
import { ShellHeader } from "@/components/shell/shell-header";
import { TimeZoneCookie } from "@/components/shell/time-zone-cookie";
import { AISidebarInset, AISidebarProvider } from "@/components/ui/ai-sidebar";
import { redirect } from "@/i18n/navigation";
import { shellConfig } from "@/lib/shell-config";

export default async function AppLayout({ children }: { children: ReactNode }) {
  const session = await getAuthSession();
  if (!session) {
    redirect({ href: "/login", locale: await getLocale() });
    return null;
  }

  const [userRecord] = await db
    .select({ onboardingCompleted: users.onboardingCompleted })
    .from(users)
    .where(eq(users.id, session.user.id))
    .limit(1);

  if (userRecord && !userRecord.onboardingCompleted) {
    redirect({ href: "/onboarding", locale: await getLocale() });
    return null;
  }

  const hdrs = await headers();
  const activeWorkspaceId = await ensureUserWorkspace(session.user, hdrs);

  const [workspaces, workspaceContext] = await Promise.all([
    auth.api.listOrganizations({ headers: hdrs }).then((orgs) => orgs ?? []),
    getWorkspaceContextById(activeWorkspaceId),
  ]);

  if (!workspaceContext) {
    redirect({ href: "/login", locale: await getLocale() });
    return null;
  }

  const workspaceList = workspaces.map((org) => ({
    id: org.id,
    name: org.name,
    slug: org.slug,
    logo: org.logo ?? null,
  }));

  // The shell is exactly one screen tall and the page region scrolls
  // inside it. A shell that grows with its page scrolls the window
  // instead, and a page that pins something to the bottom — the chat
  // composer — or scrolls its own region — the transcript — has no
  // height to work in.
  const SidebarContent = shellConfig.sidebarContent;
  return (
    <AISidebarProvider className="h-svh min-h-0 overflow-hidden">
      {/* Renders nothing; tells the server which day it is here. */}
      <TimeZoneCookie />
      <AppSidebar
        workspace={workspaceContext.workspace}
        workspaces={workspaceList}
        user={{
          name: session.user.name,
          email: session.user.email,
          image: session.user.image,
        }}
      >
        {SidebarContent ? <SidebarContent /> : null}
      </AppSidebar>
      <AISidebarInset className="min-h-0 overflow-hidden">
        <ShellHeader>
          {shellConfig.headerRight && (
            <div className="ml-auto flex items-center gap-2">
              <shellConfig.headerRight />
            </div>
          )}
        </ShellHeader>
        {shellConfig.bannerTop && <shellConfig.bannerTop />}
        <PageTransition className="min-h-0 flex-1 overflow-y-auto">
          {children}
        </PageTransition>
      </AISidebarInset>
    </AISidebarProvider>
  );
}

"use client";

/**
 * The shell's sidebar. `items` replaces the nav from `@/lib/nav-config`
 * entirely. It collapses to an icon rail on desktop (⌘/Ctrl-B, or the
 * header's trigger) and slides in as a sheet on mobile.
 */

import * as React from "react";
import { useTranslations } from "next-intl";
import type { LucideIcon } from "lucide-react";

import { Link, usePathname } from "@/i18n/navigation";
import {
  AISidebar,
  AISidebarContent,
  AISidebarFooter,
  AISidebarHeader,
  AISidebarItem,
  AISidebarMenu,
  AISidebarMenuItem,
  AISidebarRail,
  AISidebarSection,
} from "@/components/ui/ai-sidebar";
import { UserMenu } from "./user-menu";
import { WorkspaceSwitcher, type Workspace } from "./workspace-switcher";
import { navItems as configuredNavItems } from "@/lib/nav-config";

export interface NavItem {
  /**
   * A message key in the `app-shell` namespace (e.g.
   * `"sidebar.nav.dashboard"`), not a literal title.
   */
  titleKey: string;
  href: string;
  icon?: LucideIcon;
}

interface AppSidebarProps {
  workspace: Workspace | null;
  workspaces: Workspace[];
  user: {
    name: string | null;
    email: string;
    image?: string | null;
  };
  items?: NavItem[];
  /** Rendered under the navigation — `shellConfig.sidebarContent`. */
  children?: React.ReactNode;
}

export function AppSidebar({
  workspace,
  workspaces,
  user,
  items = configuredNavItems,
  children,
}: AppSidebarProps) {
  const pathname = usePathname();
  const t = useTranslations("app-shell");

  return (
    <AISidebar
      collapsible="icon"
      label={t("sidebar.label")}
      closeLabel={t("sidebar.close")}
    >
      <AISidebarHeader>
        <WorkspaceSwitcher
          currentWorkspace={workspace}
          workspaces={workspaces}
        />
      </AISidebarHeader>

      <AISidebarContent>
        <AISidebarSection>
          <AISidebarMenu>
            {items.map((item) => {
              const isActive =
                pathname === item.href || pathname?.startsWith(`${item.href}/`);
              return (
                <AISidebarMenuItem key={item.href}>
                  <AISidebarItem
                    isActive={isActive}
                    icon={item.icon ? <item.icon /> : undefined}
                    tooltip={t(item.titleKey)}
                    render={<Link href={item.href} />}
                  >
                    {t(item.titleKey)}
                  </AISidebarItem>
                </AISidebarMenuItem>
              );
            })}
          </AISidebarMenu>
        </AISidebarSection>
        {children}
      </AISidebarContent>

      <AISidebarFooter>
        <UserMenu user={user} />
      </AISidebarFooter>
      <AISidebarRail label={t("sidebar.toggle")} />
    </AISidebar>
  );
}

"use client";

/**
 * Lists the caller's workspaces (fetched by the layout) and activates one
 * through Better-Auth's organization plugin. It has no create-workspace
 * action; build one on `authClient.organization.create` if you need it.
 */

import * as React from "react";
import { toast } from "sonner";
import { useTranslations } from "next-intl";
import { Check, ChevronsUpDown } from "lucide-react";

import { authClient } from "@intelligo-dev/auth/client";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useAISidebar, useAISidebarPanel } from "@/components/ui/ai-sidebar";
import { cn } from "@/lib/utils";
import { useRouter } from "@/i18n/navigation";

const TRIGGER =
  "flex w-full min-w-0 items-center gap-2 rounded-xl p-1.5 text-left text-sidebar-foreground outline-none transition-colors hover:bg-sidebar-accent focus-visible:ring-2 focus-visible:ring-sidebar-ring disabled:opacity-50 data-popup-open:bg-sidebar-accent data-popup-open:text-sidebar-accent-foreground";

export interface Workspace {
  id: string;
  name: string;
  slug: string;
  logo?: string | null;
}

interface WorkspaceSwitcherProps {
  currentWorkspace: Workspace | null;
  workspaces: Workspace[];
}

export function WorkspaceSwitcher({
  currentWorkspace,
  workspaces,
}: WorkspaceSwitcherProps) {
  const { isMobile } = useAISidebar();
  const { collapsed } = useAISidebarPanel();
  const router = useRouter();
  const [isSwitching, setIsSwitching] = React.useState(false);
  const t = useTranslations("app-shell");

  if (!currentWorkspace) return null;

  async function handleSwitch(workspaceId: string) {
    if (!currentWorkspace || workspaceId === currentWorkspace.id) return;
    setIsSwitching(true);
    try {
      // Better-Auth answers a refusal as `{ error }` rather than throwing.
      const { error } = await authClient.organization.setActive({
        organizationId: workspaceId,
      });
      if (error) {
        toast.error(t("workspaceSwitcher.switchFailed"));
        return;
      }
      router.refresh();
    } catch {
      toast.error(t("workspaceSwitcher.switchFailed"));
    } finally {
      setIsSwitching(false);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type="button"
            disabled={isSwitching}
            className={cn(TRIGGER, collapsed && "justify-center")}
          />
        }
      >
        <div className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-sidebar-primary text-xs font-semibold text-sidebar-primary-foreground">
          {currentWorkspace.name[0]?.toUpperCase()}
        </div>
        {collapsed ? null : (
          <>
            <div className="grid min-w-0 flex-1 text-left leading-tight">
              <span className="truncate text-sm font-medium">
                {currentWorkspace.name}
              </span>
              <span className="truncate text-xs text-muted-foreground">
                {currentWorkspace.slug}
              </span>
            </div>
            {workspaces.length > 1 && (
              <ChevronsUpDown className="ml-auto size-4 opacity-50" />
            )}
          </>
        )}
      </DropdownMenuTrigger>
      {workspaces.length > 1 && (
        <DropdownMenuContent
          className="w-(--anchor-width) min-w-56"
          align="start"
          side={isMobile ? "bottom" : "right"}
          sideOffset={4}
        >
          <DropdownMenuGroup>
            <DropdownMenuLabel className="text-xs text-muted-foreground">
              {t("workspaceSwitcher.workspacesLabel")}
            </DropdownMenuLabel>
            <DropdownMenuSeparator />
            {workspaces.map((ws) => (
              <DropdownMenuItem
                key={ws.id}
                onClick={() => handleSwitch(ws.id)}
                disabled={isSwitching}
                className="gap-2"
              >
                <div className="flex size-6 shrink-0 items-center justify-center rounded-md bg-sidebar-primary text-xs font-semibold text-sidebar-primary-foreground">
                  {ws.name[0]?.toUpperCase()}
                </div>
                <div className="grid flex-1 leading-tight">
                  <span className="truncate text-sm">{ws.name}</span>
                  <span className="truncate text-xs text-muted-foreground">
                    {ws.slug}
                  </span>
                </div>
                {ws.id === currentWorkspace.id && (
                  <Check className="ml-auto size-4" />
                )}
              </DropdownMenuItem>
            ))}
          </DropdownMenuGroup>
        </DropdownMenuContent>
      )}
    </DropdownMenu>
  );
}

"use client";

/**
 * Avatar dropdown: account pages (`accountItems` from `@/lib/nav-config`),
 * settings, a theme submenu and sign out.
 *
 * The theme submenu only switches themes once a `ThemeProvider` is
 * mounted; without one `useTheme()` is a no-op. The `mounted` check
 * avoids a hydration mismatch between the server render (no theme) and
 * the client's resolved theme.
 */

import * as React from "react";
import { useTranslations } from "next-intl";
import {
  ChevronsUpDown,
  LogOut,
  Monitor,
  Moon,
  Settings,
  Sun,
  User,
} from "lucide-react";
import { useTheme } from "next-themes";

import { authClient } from "@intelligo-dev/auth/client";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Link, useRouter } from "@/i18n/navigation";
import { accountItems } from "@/lib/nav-config";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useAISidebar, useAISidebarPanel } from "@/components/ui/ai-sidebar";
import { cn } from "@/lib/utils";

const TRIGGER =
  "flex w-full min-w-0 items-center gap-2 rounded-xl p-1.5 text-left text-sidebar-foreground outline-none transition-colors hover:bg-sidebar-accent focus-visible:ring-2 focus-visible:ring-sidebar-ring disabled:opacity-50 data-popup-open:bg-sidebar-accent data-popup-open:text-sidebar-accent-foreground";

interface UserMenuProps {
  user: {
    name: string | null;
    email: string;
    image?: string | null;
  };
}

export function UserMenu({ user }: UserMenuProps) {
  const { isMobile } = useAISidebar();
  const { collapsed } = useAISidebarPanel();
  const { theme, setTheme } = useTheme();
  const [mounted, setMounted] = React.useState(false);
  const router = useRouter();
  const t = useTranslations("app-shell");

  React.useEffect(() => {
    setMounted(true);
  }, []);

  const initials = user.name
    ? user.name
        .split(" ")
        .map((part) => part[0])
        .join("")
        .toUpperCase()
        .slice(0, 2)
    : user.email[0]?.toUpperCase();

  async function handleSignOut() {
    await authClient.signOut();
    router.push("/login");
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type="button"
            className={cn(TRIGGER, collapsed && "justify-center")}
          />
        }
      >
        <Avatar className="size-8 rounded-lg">
          {user.image && <AvatarImage src={user.image} alt={user.name ?? ""} />}
          <AvatarFallback className="rounded-lg">{initials}</AvatarFallback>
        </Avatar>
        {collapsed ? null : (
          <>
            <div className="grid min-w-0 flex-1 text-left leading-tight">
              <span className="truncate text-sm font-medium">
                {user.name || user.email.split("@")[0]}
              </span>
              <span className="truncate text-xs text-muted-foreground">
                {user.email}
              </span>
            </div>
            <ChevronsUpDown className="ml-auto size-4 opacity-50" />
          </>
        )}
      </DropdownMenuTrigger>
      <DropdownMenuContent
        className="w-(--anchor-width) min-w-56"
        side={isMobile ? "bottom" : collapsed ? "right" : "top"}
        align="end"
        sideOffset={4}
      >
        <DropdownMenuGroup>
          <DropdownMenuLabel className="p-0 font-normal">
            <div className="flex items-center gap-2 px-2 py-1.5">
              <Avatar className="size-8 rounded-lg">
                {user.image && (
                  <AvatarImage src={user.image} alt={user.name ?? ""} />
                )}
                <AvatarFallback className="rounded-lg">
                  {initials}
                </AvatarFallback>
              </Avatar>
              <div className="grid flex-1 leading-tight">
                <span className="truncate text-sm font-medium">
                  {user.name || user.email.split("@")[0]}
                </span>
                <span className="truncate text-xs text-muted-foreground">
                  {user.email}
                </span>
              </div>
            </div>
          </DropdownMenuLabel>
        </DropdownMenuGroup>
        <DropdownMenuSeparator />

        <DropdownMenuGroup>
          <DropdownMenuItem render={<Link href="/settings" />}>
            <User />
            {t("userMenu.profile")}
          </DropdownMenuItem>
          <DropdownMenuItem render={<Link href="/settings/workspace" />}>
            <Settings />
            {t("userMenu.workspaceSettings")}
          </DropdownMenuItem>
        </DropdownMenuGroup>
        <DropdownMenuSeparator />

        {accountItems.length > 0 ? (
          <>
            <DropdownMenuGroup>
              {accountItems.map((item) => {
                const Icon = item.icon;
                return (
                  <DropdownMenuItem
                    key={item.href}
                    render={<Link href={item.href} />}
                  >
                    {Icon ? <Icon /> : null}
                    {t(item.titleKey)}
                  </DropdownMenuItem>
                );
              })}
            </DropdownMenuGroup>
            <DropdownMenuSeparator />
          </>
        ) : null}

        <DropdownMenuSub>
          <DropdownMenuSubTrigger>
            {mounted && theme === "dark" ? <Moon /> : <Sun />}
            {t("userMenu.theme")}
          </DropdownMenuSubTrigger>
          <DropdownMenuSubContent>
            <DropdownMenuItem onClick={() => setTheme("light")}>
              <Sun />
              {t("userMenu.themeLight")}
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => setTheme("dark")}>
              <Moon />
              {t("userMenu.themeDark")}
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => setTheme("system")}>
              <Monitor />
              {t("userMenu.themeSystem")}
            </DropdownMenuItem>
          </DropdownMenuSubContent>
        </DropdownMenuSub>

        <DropdownMenuSeparator />
        <DropdownMenuItem
          onClick={handleSignOut}
          className="text-destructive focus:text-destructive"
        >
          <LogOut />
          {t("userMenu.signOut")}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * Shell top bar. It must render `AISidebarTrigger`: on mobile the sidebar
 * is an off-canvas sheet with no other way to open it. `children` adds
 * breadcrumbs or actions. A page portals its own bar into the empty
 * `shell-header-slot` (the chat's title and actions do) rather than
 * stacking a second header under this one.
 */

import type { ReactNode } from "react";
import { getTranslations } from "next-intl/server";

import { AISidebarTrigger } from "@/components/ui/ai-sidebar";
import { Separator } from "@/components/ui/separator";

interface ShellHeaderProps {
  children?: ReactNode;
}

export async function ShellHeader({ children }: ShellHeaderProps) {
  const t = await getTranslations("app-shell");

  return (
    <header className="flex h-14 shrink-0 items-center gap-2 border-b px-4">
      <AISidebarTrigger
        size="icon-sm"
        label={t("sidebar.toggle")}
        className="-ml-1"
      />
      <div className="mr-2 flex h-4 items-center">
        <Separator orientation="vertical" />
      </div>
      <div
        data-slot="shell-header-slot"
        className="flex min-w-0 flex-1 items-center"
      />
      {children}
    </header>
  );
}

"use client";

/**
 * The user menu's Light/Dark/System submenu drives `next-themes`, which
 * is inert until this provider is mounted above it. The root layout is
 * yours, so mounting it is one manual step:
 *
 *   // app/[locale]/layout.tsx
 *   import { ThemeProvider } from "@/components/shell/theme-provider";
 *   <html lang={locale} suppressHydrationWarning>
 *     <body>
 *       <ThemeProvider>{children}</ThemeProvider>
 *     </body>
 *   </html>
 *
 * `suppressHydrationWarning` is required: next-themes sets the class
 * attribute before hydration.
 *
 * Defaults: class strategy (Tailwind's `.dark` tokens), system preference
 * honoured, no transition on switch. Props pass through to override them.
 */

import { ThemeProvider as NextThemesProvider } from "next-themes";
import type { ThemeProviderProps } from "next-themes";

export function ThemeProvider({ children, ...props }: ThemeProviderProps) {
  return (
    <NextThemesProvider
      attribute="class"
      defaultTheme="system"
      enableSystem
      disableTransitionOnChange
      {...props}
    >
      {children}
    </NextThemesProvider>
  );
}

"use client";

/**
 * The page region of the shell. Moving between sections — dashboard to
 * chat, chat to artifacts — lifts the new page in; moving inside one
 * (a conversation to the next, a settings tab to another) does not,
 * because the section's own layout owns that motion.
 *
 * It animates in place rather than keying on the route, so nothing under
 * it remounts: a layout's state survives the navigation.
 */

import * as React from "react";
import { useAnimate, useReducedMotion } from "motion/react";

import { EASE_OUT } from "@/components/ui/ai-motion";
import { usePathname } from "@/i18n/navigation";
import { cn } from "@/lib/utils";

function sectionOf(pathname: string | null) {
  return pathname?.split("/").filter(Boolean)[0] ?? "";
}

export function PageTransition({
  className,
  children,
}: {
  className?: string;
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  const reduced = useReducedMotion() ?? false;
  const [scope, animate] = useAnimate<HTMLDivElement>();
  const section = sectionOf(pathname);
  const previous = React.useRef(section);

  React.useEffect(() => {
    if (previous.current === section) return;
    previous.current = section;
    scope.current?.scrollTo({ top: 0 });
    if (reduced) return;
    const element = scope.current;
    // Cleared after: a leftover transform would make this region the
    // containing block of every fixed-position element inside the page.
    void animate(
      element,
      { opacity: [0, 1], y: [8, 0] },
      { duration: 0.36, ease: EASE_OUT }
    ).then(() => {
      element.style.transform = "";
      element.style.opacity = "";
    });
  }, [animate, reduced, scope, section]);

  return (
    <div ref={scope} data-slot="page" className={cn(className)}>
      {children}
    </div>
  );
}

"use client";

/**
 * Writes the browser's time zone to a cookie so per-day figures bucket
 * in the reader's day rather than UTC. The server reads it through
 * `@intelligo-dev/core/request-context`; a browser's time zone reaches the
 * server no other way. The first render of a new session has no cookie
 * yet and buckets in UTC.
 */

import { useEffect } from "react";

const COOKIE = "tz";
const ONE_YEAR_SECONDS = 60 * 60 * 24 * 365;

export function TimeZoneCookie() {
  useEffect(() => {
    const zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    if (!zone) return;

    const current = document.cookie.match(/(?:^|;\s*)tz=([^;]*)/)?.[1];
    if (current && decodeURIComponent(current) === zone) return;

    // Lax: this rides same-site navigation, and it is a display
    // preference, not a credential.
    document.cookie = `${COOKIE}=${encodeURIComponent(zone)}; path=/; max-age=${ONE_YEAR_SECONDS}; samesite=lax`;
  }, []);

  return null;
}

/**
 * What your product adds around the app shell, without editing
 * `layout.tsx` or `components/shell/*`. Every slot is optional and takes
 * a component with no props; one that needs data fetches it itself.
 *
 *  - `bannerTop`: above the page content on every authenticated page
 *    (a trial banner, an incident notice).
 *  - `headerRight`: the right end of the header (a notification bell,
 *    a language switcher).
 *  - `sidebarContent`: the sidebar under the navigation (conversation
 *    history). May be an async server component; it refreshes with the
 *    page. Hiding itself when the sidebar collapses is its own call.
 *
 * For example:
 *
 *   import { TrialBanner } from "@/components/trial/trial-banner";
 *
 *   export const shellConfig: ShellConfig = {
 *     bannerTop: TrialBanner,
 *   };
 */

import type { ComponentType } from "react";

export interface ShellConfig {
  /** Rendered inside `SidebarInset`, above `main`. Takes no props. */
  bannerTop?: ComponentType;
  /**
   * Rendered at the right end of the shell header — e.g. a
   * notification bell, a language switcher, or both. Takes no props.
   */
  headerRight?: ComponentType;
  /**
   * Rendered in the sidebar under the navigation — e.g. conversation
   * history. Takes no props; may be an async server component.
   */
  sidebarContent?: ComponentType;
}

export const shellConfig: ShellConfig = {};

{
  "sidebar": {
    "label": "Main navigation",
    "toggle": "Toggle sidebar",
    "close": "Close sidebar",
    "nav": {
      "dashboard": "Dashboard",
      "chat": "Chat",
      "artifacts": "Artifacts"
    }
  },
  "userMenu": {
    "profile": "Profile",
    "workspaceSettings": "Workspace settings",
    "usage": "Usage",
    "pricing": "Pricing",
    "theme": "Theme",
    "themeLight": "Light",
    "themeDark": "Dark",
    "themeSystem": "System",
    "signOut": "Sign out"
  },
  "workspaceSwitcher": {
    "workspacesLabel": "Workspaces",
    "switchFailed": "Couldn't switch workspace. Please try again."
  }
}

/**
 * Shell navigation. Imported directly by client components, never passed
 * from a Server Component: icons are components and cannot cross the
 * server/client boundary.
 *
 * `navItems` fills the sidebar; `accountItems` fills the user menu.
 * `titleKey`s are keys in `messages/<locale>/app-shell.json`. Remove the
 * entries whose routes you did not install; they would 404.
 */

